 ],
 "publisher": "Gump South Pacific Research Station",
 "publicationYear": 2024,
 "types": {
  "schemaOrg": "CreativeWork",
  "resourceTypeGeneral": "Project",
  "citeproc": "article",
  "bibtex": "misc",
  "ris": "GEN",
  "resourceType": "Project"
 },
 "descriptions": [
  {
   "descriptionType": "Abstract",
   "description": "This study investigates the ecological impacts of land use change, particularly focusing on the vegetation near the Temae Golf Course on Moorea, French Polynesia. Through field surveys conducted by the 2024 Island Sustainability Program cohort, we compare plant diversity and composition in pristine and cultivated areas adjacent to the golf course. Our findings highlight significant differences, with cultivated areas exhibiting lower diversity and a higher proportion of introduced species. These results underscore the potential risks associated with tourism-driven land development, including the introduction of invasive species and the loss of ecosystem resilience. By shedding light on these impacts, our study emphasizes the importance of integrating conservation efforts with tourism development to ensure the long-term sustainability of Moorea’s ecosystems.",
   "lang": "en"
  }
 ],
 "geoLocations": [
  {
   "geoLocationPlace": "Gump South Pacific Research Station"
  }
 ],
